WITH valid AS (SELECT id, account_id, txn_type, amount, merchant, is_flagged, TO_DATE(txn_time) AS txn_time_date, COALESCE(merchant, 'OTHER') AS merchant_clean FROM transactions WHERE merchant IS NOT NULL) SELECT *, STDDEV_SAMP(amount) OVER (PARTITION BY merchant, account_id) AS merchant_stddev_samp_amount, LAG(amount, 1) OVER (PARTITION BY txn_type ORDER BY amount, id) AS prev_amount, SUM(amount) OVER (PARTITION BY txn_type ORDER BY txn_time_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount FROM valid;
